  function renderFullRecords(records){const root=$('full-records');root.replaceChildren();root.append(node('h3','Full officer source details'),node('p','Original reported subject records, grouped by dataset. These are the last verified records, not a newly verified current state.','small muted'));if(!records.length){root.append(node('p','Full source details have not been imported for this officer.'));return;}const groups=new Map();for(const record of records){if(!groups.has(record.dataset))groups.set(record.dataset,[]);groups.get(record.dataset).push(record);}const priority=dataset=>dataset==='officer_personal_information.csv'?0:dataset==='officer_service_information.csv'?1:2;for(const [dataset,rows] of [...groups.entries()].sort((a,b)=>priority(a[0])-priority(b[0])||a[0].localeCompare(b[0]))){const section=node('details',null,'card');section.open=priority(dataset)<2;section.append(node('summary',words(dataset.replace(/\.csv$/,''))+' · '+rows.length+' record(s)'));for(const row of rows){const record=node('article',null,'evidence-item');const fields=node('dl');for(const [name,value] of Object.entries(row.fields)){fields.append(node('dt',words(name)),node('dd',value||'Not recorded'));}record.append(fields,details('Source record reference',row.raw_record_id));section.append(record);}root.append(section);}}
